/** Licensed Fab subset: repair atlas bindings, then use the engine's meshopt/UASTC cook.
 * FAB_TEMPERATE=<imported library> node scripts/prep-fab-temperate.mjs
 * All generated bytes stay in gitignored local-assets/temperate (120 MB maximum).
 */
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import { basename, dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const EXAMPLE = fileURLToPath(new URL("..", import.meta.url));
const REPO = join(EXAMPLE, "..", "..");
const LIBRARY = process.env.FAB_TEMPERATE;
if (!LIBRARY) throw new Error("Set FAB_TEMPERATE to the imported Fab library.");
const OUT = join(EXAMPLE, "local-assets/temperate");
const STAGE = join(EXAMPLE, "local-assets/.temperate-stage");
const requireAssets = createRequire(join(REPO, "packages/assets/package.json"));
const sharp = requireAssets("sharp");
const { MeshoptSimplifier } = requireAssets("meshoptimizer");
await MeshoptSimplifier.ready;
const { NodeIO } = requireAssets("@gltf-transform/core");
const {
  dedup,
  join: joinMeshes,
  weld,
  simplify,
  normals,
} = requireAssets("@gltf-transform/functions");
const { compileAssets } = await import(pathToFileURL(join(REPO, "packages/assets/dist/index.js")));
const io = new NodeIO();
const set = (albedo, normal, mask = null, channel = 0) => ({ albedo, normal, mask, channel });
const atlases = {
  "spruce-forest": {
    trunk: set("Bark_A_", "Moss_N"),
    branch: set("Branch_A", "Branch_N"),
    leaf: set("Leaf_A_02", "Leaf_N", "Leaf_O"),
  },
  "grass-library": set(
    "springGrass_Albedo_8k_I",
    "springGrass_Normal_springGrass_8k",
    "springGrass_Opacity_8k",
  ),
  "ground-foliage": set("Foilage_Ground_Main_A", "Foilage_Ground_Main_N", "Foilage_Ground_Main_O"),
  "meadow-flowers": set("Combined_Flowers_A", "Combined_Flowers_N", "Combined_Flowers_O"),
  "fern-collection": set("fern_01_A", "fern_01_N", "fern_01_AORO", 2),
};
const models = [];
const add = (pack, name, logical) => models.push({ pack, name, logical });
for (let i = 0; i < 3; i++) add("spruce-forest", `spruce_full_0${i + 1}_low`, `spruce/${i}`);
for (let i = 0; i < 2; i++) add("spruce-forest", `spruce_half_0${i + 1}_low`, `spruce/${i + 3}`);
for (let i = 0; i < 3; i++) add("spruce-forest", `spruce_small_0${i + 1}`, `sapling/${i}`);
for (const [i, name] of [
  "grass_01_01_mesh",
  "grass_02_05_mesh",
  "grass_03_01_mesh",
  "grass_01_04_mesh",
].entries())
  add("grass-library", name, `grass/${i}`);
for (const [i, name] of ["flower_15_05", "flower_07_01", "flower_01_01", "flower_14_04"].entries())
  add("meadow-flowers", name, `poppy/${i}`);
for (let i = 0; i < 3; i++) add("ground-foliage", `ground_0${i + 1}_01`, `scrub/${i}`);
for (let i = 0; i < 2; i++) add("fern-collection", `fern_0${i + 1}_01`, `fern/${i}`);
for (const [name, logical] of [
  ["SM_Boulder05a", "boulder/0"],
  ["SM_LargePlainsBoulder002", "boulder/1"],
  ["Medium_Boulder_001", "boulder/2"],
  ["SM_River_Rock_01", "riverrock/0"],
  ["Scree_001", "scree/0"],
  ["SM_Cliff01", "cliff/0"],
])
  add("open-world-demo", name, logical);

function* files(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* files(path);
    else yield path;
  }
}
const atlasFiles = new Map();
for (const pack of Object.keys(atlases)) {
  const root = join(LIBRARY, pack, "textures");
  for (const path of files(existsSync(root) ? root : join(LIBRARY, pack)))
    atlasFiles.set(`${pack}/${basename(path)}`, path);
}
const images = new Map();
async function imageBytes(pack, spec, normal = false) {
  const key = `${pack}/${JSON.stringify(spec)}/${normal}`;
  if (images.has(key)) return images.get(key);
  const path = (name) => {
    const found = atlasFiles.get(`${pack}/${name}.png`);
    if (!found) throw new Error(`Missing ${pack}/${name}.png`);
    return found;
  };
  const resized = sharp(path(normal ? spec.normal : spec.albedo))
    .resize(2048, 2048, { fit: "inside", withoutEnlargement: true })
    .removeAlpha();
  let result = await resized.png().toBuffer();
  if (!normal && spec.mask) {
    const metadata = await sharp(result).metadata();
    const alpha = await sharp(path(spec.mask))
      .resize(metadata.width, metadata.height)
      .removeAlpha()
      .extractChannel(spec.channel)
      .png()
      .toBuffer();
    result = await sharp(result).joinChannel(alpha).png().toBuffer();
  }
  images.set(key, result);
  return result;
}
const align = (value) => (value + 3) & ~3;
function glb(json, binary) {
  const encoded = Buffer.from(JSON.stringify(json));
  const j = Buffer.alloc(align(encoded.length), 0x20);
  encoded.copy(j);
  const b = Buffer.alloc(align(binary.length));
  binary.copy(b);
  const head = Buffer.alloc(20);
  head.writeUInt32LE(0x46546c67, 0);
  head.writeUInt32LE(2, 4);
  head.writeUInt32LE(28 + j.length + b.length, 8);
  head.writeUInt32LE(j.length, 12);
  head.writeUInt32LE(0x4e4f534a, 16);
  const bh = Buffer.alloc(8);
  bh.writeUInt32LE(b.length, 0);
  bh.writeUInt32LE(0x004e4942, 4);
  return Buffer.concat([head, j, bh, b]);
}
async function prepare(source, pack) {
  const data = readFileSync(source);
  const length = data.readUInt32LE(12);
  const json = JSON.parse(data.toString("utf8", 20, 20 + length));
  const binary = data.subarray(28 + length);
  const buffers = [];
  let cursor = 0;
  const append = (bytes, view = {}) => {
    const start = cursor;
    cursor = align(cursor + bytes.length);
    const padded = Buffer.alloc(cursor - start);
    bytes.copy(padded);
    buffers.push(padded);
    return { ...view, buffer: 0, byteOffset: start, byteLength: bytes.length };
  };
  // The importer can leave views unaligned. Rebuild every view with exact lengths and aligned gaps.
  json.bufferViews = json.bufferViews.map((view) =>
    append(binary.subarray(view.byteOffset ?? 0, (view.byteOffset ?? 0) + view.byteLength), view),
  );
  const widths = { scalar: 1, vec2: 2, vec3: 3, vec4: 4 };
  const bytes = { 5120: 1, 5121: 1, 5122: 2, 5123: 2, 5125: 4, 5126: 4 };
  for (const accessor of json.accessors) {
    const view = json.bufferViews[accessor.bufferView];
    const held = Math.floor(
      (view.byteLength - (accessor.byteOffset ?? 0)) /
        (view.byteStride ?? widths[accessor.type.toLowerCase()] * bytes[accessor.componentType]),
    );
    accessor.count = Math.min(accessor.count, held);
    if (!(accessor.count > 0)) throw new Error(`Empty accessor in ${source}`);
  }
  if (atlases[pack]) {
    json.images = [];
    json.textures = [];
    json.samplers = [{ magFilter: 9729, minFilter: 9987, wrapS: 10497, wrapT: 10497 }];
    const embedded = new Map();
    const embed = async (spec, normal = false) => {
      const key = `${JSON.stringify(spec)}/${normal}`;
      if (embedded.has(key)) return embedded.get(key);
      const png = await imageBytes(pack, spec, normal);
      json.bufferViews.push(append(png));
      json.images.push({ bufferView: json.bufferViews.length - 1, mimeType: "image/png" });
      json.textures.push({ source: json.images.length - 1, sampler: 0 });
      const index = json.textures.length - 1;
      embedded.set(key, index);
      return index;
    };
    for (const material of json.materials) {
      const spec =
        pack === "spruce-forest" ? atlases[pack][material.name.split("_").at(-1)] : atlases[pack];
      if (!spec) throw new Error(`No atlas for ${pack}/${material.name}`);
      material.pbrMetallicRoughness = {
        baseColorFactor: [1, 1, 1, 1],
        baseColorTexture: { index: await embed(spec) },
        metallicFactor: 0,
        roughnessFactor: 0.9,
      };
      material.normalTexture = { index: await embed(spec, true) };
      material.occlusionTexture = undefined;
      material.emissiveTexture = undefined;
      material.alphaMode = spec.mask ? "MASK" : "OPAQUE";
      material.alphaCutoff = 0.42;
      material.doubleSided = !!spec.mask;
      // Identical section names may repeat hundreds of times; dedup + join collapses them.
      material.name = pack === "spruce-forest" ? material.name.split("_").at(-1) : pack;
    }
  }
  json.buffers = [{ byteLength: cursor }];
  const document = await io.readBinary(glb(json, Buffer.concat(buffers)));
  // One full-spruce import contains all-zero normals; do not preserve them into every cook/LOD.
  let repair = false;
  for (const mesh of document.getRoot().listMeshes())
    for (const primitive of mesh.listPrimitives()) {
      const normal = primitive.getAttribute("NORMAL");
      if (!normal || normal.getArray().every((value) => value === 0)) {
        primitive.setAttribute("NORMAL", null);
        repair = true;
      }
    }
  if (repair) await document.transform(normals());
  await document.transform(dedup(), joinMeshes(), weld());
  return io.writeBinary(document);
}
mkdirSync(STAGE, { recursive: true });
for (const { pack, name, logical } of models) {
  const report = JSON.parse(readFileSync(join(LIBRARY, pack, "import-report.json"), "utf8"));
  const model = report.models.find((entry) => entry.name === name);
  if (!model) throw new Error(`Import report has no ${pack}/${name}`);
  const target = join(STAGE, `${logical}.glb`);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, await prepare(join(LIBRARY, pack, model.glb), pack));
  console.log(`[prep] ${logical}: ${name}`);
  if (logical.startsWith("spruce/")) {
    const low = await io.read(target);
    await low.transform(simplify({ simplifier: MeshoptSimplifier, ratio: 0.14, error: 0.012 }));
    await io.write(join(STAGE, `${logical}-far.glb`), low);
  }
}
await compileAssets({
  source: ".",
  output: OUT,
  cwd: STAGE,
  config: { models: { textures: { maxSize: 2048 }, virtual: "none" }, textures: { maxSize: 2048 } },
});
const manifest = JSON.parse(readFileSync(join(OUT, "assets.manifest.json"), "utf8"));
for (const [logical, entry] of Object.entries(manifest.entries))
  if (logical.endsWith(".glb")) copyFileSync(join(OUT, entry.output), join(OUT, logical));
const transcoder = createRequire(join(EXAMPLE, "package.json")).resolve(
  "three/examples/jsm/libs/basis/basis_transcoder.js",
);
mkdirSync(join(OUT, "basis"), { recursive: true });
for (const name of ["basis_transcoder.js", "basis_transcoder.wasm"])
  copyFileSync(join(dirname(transcoder), name), join(OUT, "basis", name));
const total = [...files(OUT)].reduce((sum, path) => sum + statSync(path).size, 0);
console.log(`[prep] ${models.length} models, ${(total / 1048576).toFixed(1)} MiB (local-only)`);
if (total > 120_000_000) throw new Error("Cook exceeds 120 MB");
